import hashlib as _hashlib
def _compute_build():
    try:
        with open(__file__, 'rb') as _f:
            return _hashlib.md5(_f.read()).hexdigest()[:12]
    except Exception:
        return "unknown"
WORKER_BUILD = _compute_build()
