def _ensure_camoufox():
    """Auto-install Camoufox - required for BROWSER_MODE=firefox.

    Camoufox is the Firefox-side equivalent of Patchright. Plain Playwright
    Firefox cannot log in: Google's OAuth refuses it with "This browser or app
    may not be secure" because navigator.webdriver is true.

    Requires >=0.5.4 (FF152). On 0.4.11 (FF135), Playwright's Node driver dies
    on any page error (pageError.location.url undefined), which presents as a
    dead browser and an expired session rather than a version problem.
    """
    try:
        import camoufox  # noqa: F401
        print("[Init] Camoufox already installed", flush=True)
        return True
    except ImportError:
        pass

    print("[Init] Camoufox not found - installing (required for firefox mode)...", flush=True)
    for cmd, label in (
        ([sys.executable, "-m", "pip", "install", "camoufox>=0.5.4"], "pip install"),
        ([sys.executable, "-m", "pip", "install", "--user", "camoufox>=0.5.4"], "pip install --user"),
    ):
        try:
            r = subprocess.run(cmd, capture_output=True, text=True, timeout=300)
            if r.returncode == 0:
                print(f"[Init] {label} succeeded", flush=True)
                break
            print(f"[Init] {label} failed (rc={r.returncode}): {r.stderr[:200]}", flush=True)
        except Exception as e:
            print(f"[Init] {label} exception: {e}", flush=True)
    else:
        print("[Init] ERROR: could not install camoufox - firefox mode will not start", flush=True)
        return False

    try:
        subprocess.run([sys.executable, "-m", "camoufox", "fetch"],
                       capture_output=True, text=True, timeout=600)
        print("[Init] Camoufox browser fetched", flush=True)
    except Exception as e:
        print(f"[Init] WARNING: camoufox fetch failed ({e}) - launch may fail", flush=True)
    return True

# Firefox must NOT use Patchright — its chromium-only patches break Firefox's
# page.evaluate ("Cannot read properties of undefined (reading '_client')").
# Decided here because this import runs long before the module-level
# BROWSER_MODE is defined, so read the env directly.
def _bootstrap_browser_driver():
    """Import browser_driver, self-healing if the worker does not have it yet.

    ORDERING TRAP: the companion-module sync lives in check_for_updates(), which
    only runs under `if __name__ == "__main__"` — i.e. AFTER this module has
    finished importing. So the very first time a worker auto-updates to a
    flow_worker.py that imports browser_driver, the file is not on disk yet and
    the import dies with ModuleNotFoundError before the sync can ever fetch it.
    That bricks EVERY updating worker, Chrome ones included (observed 2026-08-07).

    Fetch it here instead, from the same endpoint the companion sync uses.
    """
    import urllib.request

    base = (os.environ.get("WEB_APP_URL") or "https://kavenobuilder.com").rstrip("/")
    dest = os.path.join(os.path.dirname(os.path.abspath(__file__)), "browser_driver.py")
    url = f"{base}/api/user-worker/download/browser_driver.py"

    # Refresh BEFORE importing, not just when missing. The companion sync in
    # check_for_updates() runs under __main__, i.e. AFTER this module has already
    # imported browser_driver — so it writes the new file to disk while the OLD
    # one is live in memory, and every companion is permanently one launch
    # behind. Measured 2026-08-10: worker started 23:49:46, browser_driver.py was
    # rewritten 23:49:55, and the run used the stale module all night (the audio
    # mute prefs never reached the browser).
    #
    # Fail-soft in every direction: any network problem falls through to whatever
    # copy is already on disk. Only a missing module AND a failed fetch is fatal.
    try:
        req = urllib.request.Request(url, headers={"User-Agent": "flow-worker"})
        with urllib.request.urlopen(req, timeout=20) as r:
            data = r.read()
        if data and data.lstrip().startswith(b'"""'):
            old = b""
            if os.path.isfile(dest):
                try:
                    with open(dest, "rb") as f:
                        old = f.read()
                except OSError:
                    pass
            if data != old:
                with open(dest, "wb") as f:
                    f.write(data)
                print(f"[Init] browser_driver refreshed ({len(data)} bytes)", flush=True)
    except Exception as e:
        print(f"[Init] browser_driver refresh skipped ({str(e)[:80]}) - using local copy",
              flush=True)

    try:
        import browser_driver as _m
        return _m
    except ImportError:
        print("[Init] FATAL: browser_driver missing and could not be fetched.", flush=True)
        print("[Init] Worker cannot start. Re-run the installer or check WEB_APP_URL.", flush=True)
        raise


_bd = _bootstrap_browser_driver()
_BROWSER_MODE_EARLY = _bd.resolve_browser_mode()

