# Single account config (legacy)
def _engine_session_folder(env_key, default):
    """Session dir for the CURRENT engine, remapping a chrome-named value.

    The installer writes SESSION_FOLDER=...\\chrome-session unconditionally, and
    single-account mode (`flow_worker.py --single`, which start_worker.bat uses)
    treats that value as authoritative. In Firefox mode that points the worker at
    a Chrome profile directory, so get_golden_folder() looks for chrome-golden,
    finds none, skips the ff-pull entirely, and the worker lands on the Google
    sign-in page with no way to log in (observed 2026-08-09).

    A Chrome profile is unreadable by Firefox, so a chrome-named dir in Firefox
    mode is ALWAYS wrong. Remap the prefix instead of trusting it. Chrome mode is
    untouched.
    """
    val = os.environ.get(env_key, default)
    if _bd.is_firefox_mode(_BROWSER_MODE_EARLY):
        base, name = os.path.split(val.rstrip("\\/"))
        if name.startswith("chrome-"):
            return os.path.join(base, "firefox-" + name[len("chrome-"):])
        if name.startswith("flow_session_chrome"):
            return os.path.join(base, name.replace("chrome", "firefox", 1))
    return val


SESSION_FOLDER = _engine_session_folder("SESSION_FOLDER", "./flow_session_chrome")
DOWNLOAD_SESSION_FOLDER = _engine_session_folder(
    "DOWNLOAD_SESSION_FOLDER", "./flow_session_chrome_download")
CACHE_FILE = "./worker_cache.json"


def suppress_chrome_signin_dialog(user_data_dir):
    """Write Chrome preferences to suppress the 'Sign in to Chrome?' dialog
    and force English UI language. Must be called BEFORE launching the browser.
    """
    import json as _json
    
    # ---- 1. Default/Preferences (per-profile settings) ----
    prefs_dir = os.path.join(user_data_dir, "Default")
    os.makedirs(prefs_dir, exist_ok=True)
    prefs_file = os.path.join(prefs_dir, "Preferences")
    
    prefs = {}
    if os.path.exists(prefs_file):
        try:
            with open(prefs_file, 'r', encoding='utf-8') as f:
                prefs = _json.load(f)
        except Exception:
            prefs = {}
    
    # Suppress sign-in prompts
    if "signin" not in prefs:
        prefs["signin"] = {}
    prefs["signin"]["allowed"] = False
    prefs["signin"]["allowed_on_next_startup"] = False
    
    if "browser" not in prefs:
        prefs["browser"] = {}
    prefs["browser"]["signin_intercept_enabled"] = False
    
    if "profile" not in prefs:
        prefs["profile"] = {}
    prefs["profile"]["default_content_setting_values"] = prefs.get("profile", {}).get("default_content_setting_values", {})
    
    # Force English language in profile
    if "intl" not in prefs:
        prefs["intl"] = {}
    prefs["intl"]["accept_languages"] = "en-US,en"
    prefs["intl"]["selected_languages"] = "en-US,en"
    
    # Disable translate popups
    if "translate" not in prefs:
        prefs["translate"] = {}
    prefs["translate"]["enabled"] = False
    
    try:
        with open(prefs_file, 'w', encoding='utf-8') as f:
            _json.dump(prefs, f)
    except Exception as e:
        print(f"[Config] Warning: Could not write Chrome prefs: {e}", flush=True)
    
    # ---- 2. Local State (browser-wide settings — controls Chrome UI language) ----
    local_state_file = os.path.join(user_data_dir, "Local State")
    local_state = {}
    if os.path.exists(local_state_file):
        try:
            with open(local_state_file, 'r', encoding='utf-8') as f:
                local_state = _json.load(f)
        except Exception:
            local_state = {}
    
    # This is the key setting that controls Chrome's UI language
    if "intl" not in local_state:
        local_state["intl"] = {}
    local_state["intl"]["app_locale"] = "en-US"
    local_state["intl"]["accept_languages"] = "en-US,en"
    
    # Also set application_locale which some Chrome versions use
    if "browser" not in local_state:
        local_state["browser"] = {}
    local_state["browser"]["application_locale"] = "en-US"
    
    try:
        with open(local_state_file, 'w', encoding='utf-8') as f:
            _json.dump(local_state, f)
    except Exception as e:
        print(f"[Config] Warning: Could not write Local State: {e}", flush=True)
    
    # ---- 3. Also set Preferences in any other profile dirs (Profile 1, etc.) ----
    for entry in os.listdir(user_data_dir):
        profile_dir = os.path.join(user_data_dir, entry)
        if os.path.isdir(profile_dir) and entry.startswith("Profile"):
            pf = os.path.join(profile_dir, "Preferences")
            pp = {}
            if os.path.exists(pf):
                try:
                    with open(pf, 'r', encoding='utf-8') as f:
                        pp = _json.load(f)
                except Exception:
                    pp = {}
            if "intl" not in pp:
                pp["intl"] = {}
            pp["intl"]["accept_languages"] = "en-US,en"
            pp["intl"]["selected_languages"] = "en-US,en"
            if "translate" not in pp:
                pp["translate"] = {}
            pp["translate"]["enabled"] = False
            try:
                with open(pf, 'w', encoding='utf-8') as f:
                    _json.dump(pp, f)
            except Exception:
                pass


def get_golden_folder(session_folder):
    """Derive the golden (baseline) folder path from a session folder path.

    Naming convention (mirrors setup_worker.py):
        .../chrome-session        → .../chrome-golden
        .../chrome-session-2      → .../chrome-golden-2
        .../flow_session_account1 → .../flow_golden_account1  (fallback)
    """
    import re
    p = os.path.abspath(session_folder)
    base = os.path.dirname(p)
    name = os.path.basename(p)

    # Standard naming from setup_worker.py
    if name == "chrome-session":
        return os.path.join(base, "chrome-golden")
    m = re.match(r"^chrome-session(-\d+)$", name)
    if m:
        return os.path.join(base, f"chrome-golden{m.group(1)}")

    # Fallback: replace "session" with "golden" anywhere in the name
    new_name = name.replace("session", "golden")
    if new_name != name:
        return os.path.join(base, new_name)

    # Last resort: just append -golden
    return os.path.join(base, name + "-golden")


def _parse_user_data_dir_from_cmdline(cmdline):
    """Extract the --user-data-dir value from a Chrome commandline string.

    Returns the path string, or None if not found. Handles three forms:
        --user-data-dir=PATH                (no quotes, no spaces in PATH)
        --user-data-dir="PATH WITH SPACES"  (double-quoted)
        --user-data-dir PATH                (separate token; rare on Chrome)

    The returned path is os.path.abspath-normalized for comparison.
    """
    if not cmdline:
        return None
    import re as _re
    # Form 1+2: --user-data-dir=value (quoted or unquoted, captures up to
    # closing quote OR up to next whitespace OR end-of-string).
    m = _re.search(r'--user-data-dir=("([^"]*)"|(\S+))', cmdline)
    if m:
        return os.path.abspath(m.group(2) if m.group(2) is not None else m.group(3))
    # Form 3: --user-data-dir PATH (separate token)
    m = _re.search(r'--user-data-dir\s+(?:"([^"]*)"|(\S+))', cmdline)
    if m:
        return os.path.abspath(m.group(1) if m.group(1) is not None else m.group(2))
    return None


def kill_chrome_using_profile(profile_dir, label=""):
    """Force-kill any browser process holding a lock on the given profile directory.
    Also removes SingletonLock/Socket/Cookie files so the next launch starts clean.
    Works on both Linux (pgrep/kill) and Windows (WMIC/taskkill).

    v684 — EXACT-MATCH on the parsed --user-data-dir value, not substring.
    Pre-v684 used `commandline like '%PATH%'` which is substring match.
    Concrete failure: if Account 1's profile is "...\\chrome-session" and
    Account 2's is "...\\chrome-session-2", a kill targeting Account 1
    matched BOTH accounts' Chrome processes (because "chrome-session" is
    a substring of "chrome-session-2"). Result: killing one account
    accidentally killed the other's browser window mid-session.

    Firefox fix: match the process name(s) for the CURRENT BROWSER_MODE
    (via browser_driver.browser_process_names) instead of a hardcoded
    "chrome.exe". Before this fix, a Firefox worker's golden restore
    called this function, matched nothing, and the subsequent
    shutil.rmtree(..., ignore_errors=True) silently half-failed against
    a still-live Firefox process, leaving the profile corrupt with no
    error anywhere. Observed live 2026-08-07: "[STARTUP] No worker Chrome
    process found for profile ...flow_session_firefox".
    """
    import subprocess as _sub
    import platform as _platform
    prefix = f"[{label}] " if label else ""
    abs_profile = os.path.abspath(profile_dir)
    killed = []
    proc_names = _bd.browser_process_names(BROWSER_MODE)

    try:
        if _platform.system() == "Windows":
            # v684 — fetch (PID, CommandLine) for every matching browser
            # process and filter in Python with EXACT match on the parsed
            # --user-data-dir value. No substring LIKE in WMIC/PowerShell —
            # too many false positives when account profile paths share a
            # common prefix.
            pid_to_cmdline = {}
            name_clause_wmic = " or ".join(f'name="{n}"' for n in proc_names)
            name_clause_ps = " or ".join(f"name='{n}'" for n in proc_names)

            # Method 1: WMIC (Windows 10 and earlier)
            try:
                r = _sub.run(
                    ['wmic', 'process', 'where', f'({name_clause_wmic})',
                     'get', 'ProcessId,CommandLine', '/format:list'],
                    capture_output=True, text=True, timeout=8
                )
                # WMIC /format:list emits blocks of `Key=Value` lines separated
                # by blank lines. Group them into (PID, CommandLine) tuples.
                current = {}
                for line in r.stdout.splitlines():
                    line = line.strip()
                    if not line:
                        if 'ProcessId' in current:
                            pid = current.get('ProcessId', '').strip()
                            cmd = current.get('CommandLine', '')
                            if pid.isdigit() and cmd:
                                pid_to_cmdline[pid] = cmd
                        current = {}
                    elif '=' in line:
                        k, _, v = line.partition('=')
                        current[k.strip()] = v
                # Flush trailing block
                if 'ProcessId' in current:
                    pid = current.get('ProcessId', '').strip()
                    cmd = current.get('CommandLine', '')
                    if pid.isdigit() and cmd:
                        pid_to_cmdline[pid] = cmd
            except Exception:
                # WMIC not available (Windows 11+) — try PowerShell
                try:
                    ps_cmd = (
                        f"Get-CimInstance Win32_Process -Filter \"({name_clause_ps})\""
                        " | Select-Object ProcessId,CommandLine"
                        " | ForEach-Object { \"$($_.ProcessId)`t$($_.CommandLine)\" }"
                    )
                    r2 = _sub.run(
                        ['powershell', '-NoProfile', '-Command', ps_cmd],
                        capture_output=True, text=True, timeout=8
                    )
                    for line in r2.stdout.splitlines():
                        line = line.rstrip('\r\n')
                        if not line:
                            continue
                        # Tab-separated PID and CommandLine
                        parts = line.split('\t', 1)
                        if len(parts) == 2 and parts[0].strip().isdigit():
                            pid_to_cmdline[parts[0].strip()] = parts[1]
                except Exception as _ps_err:
                    print(f"{prefix}PowerShell CIM query failed (non-fatal): {_ps_err}", flush=True)

            # v684 — EXACT match on parsed --user-data-dir value
            pids_found = []
            for pid, cmdline in pid_to_cmdline.items():
                udd = _parse_user_data_dir_from_cmdline(cmdline)
                if udd is None:
                    # Browser process without --user-data-dir flag (probably
                    # the user's personal Chrome) — skip.
                    continue
                # Normalize both sides for comparison: case-insensitive on
                # Windows, trailing slash stripped, abspath-normalized.
                if udd.rstrip('\\/').lower() == abs_profile.rstrip('\\/').lower():
                    pids_found.append(pid)

            for pid in pids_found:
                _sub.run(['taskkill', '/F', '/PID', pid], capture_output=True, timeout=5)
                print(f"{prefix}Killed worker browser pid {pid} (profile: {os.path.basename(abs_profile)})", flush=True)
                killed.append(pid)

            # v701g — give Windows a moment to release the killed processes'
            # file handles BEFORE the caller does the golden-restore copy.
            # Without this, restore hits WinError 1224 ("file with user-
            # mapped section open") on Chrome's cookie / cache databases
            # because their shared-memory mappings outlive the process exit
            # by a couple of seconds. Restore retry loop will still catch
            # leftovers but a 1.5s breather here cuts most of them.
            if killed and len(killed) > 0:
                time.sleep(1.5)

            # NOTE: We intentionally do NOT fall back to 'taskkill /IM chrome.exe'
            # OR to a basename search. Exact full-path match is the only safe way
            # to distinguish this account's browser from (a) the user's personal
            # Chrome, (b) OTHER accounts' browser (this video worker's accounts
            # share parent paths), and (c) OTHER workers' browser (image worker).
            if not killed:
                print(f"{prefix}No worker browser process found for profile {abs_profile}", flush=True)
        else:
            # Linux/Mac: parse commandlines from /proc, do exact --user-data-dir
            # match. v684 — same fix as Windows side above. pre-v684 used
            # `pgrep -f abs_profile` which is substring match → cross-account kills.
            proc_names_linux = [n[:-4] if n.lower().endswith('.exe') else n for n in proc_names]
            try:
                # Iterate /proc/<pid>/cmdline files
                for pid_dir in os.listdir('/proc'):
                    if not pid_dir.isdigit():
                        continue
                    cmdline_path = f'/proc/{pid_dir}/cmdline'
                    try:
                        with open(cmdline_path, 'rb') as f:
                            raw = f.read()
                    except Exception:
                        continue
                    # /proc cmdline is NUL-separated; reassemble with spaces
                    # for the regex parser.
                    cmdline = raw.replace(b'\x00', b' ').decode('utf-8', errors='replace').strip()
                    if not any(pn.lower() in cmdline.lower() for pn in proc_names_linux):
                        continue
                    udd = _parse_user_data_dir_from_cmdline(cmdline)
                    if udd is None:
                        continue
                    if udd.rstrip('/').lower() == abs_profile.rstrip('/').lower():
                        try:
                            _sub.run(['kill', '-9', pid_dir], capture_output=True, timeout=5)
                            print(f"{prefix}Killed stale browser pid {pid_dir} (profile: {os.path.basename(abs_profile)})", flush=True)
                            killed.append(pid_dir)
                        except Exception:
                            pass
            except Exception:
                pass

        if not killed:
            print(f"{prefix}No stale browser found for {os.path.basename(abs_profile)}", flush=True)
    except Exception as e:
        print(f"{prefix}Could not kill browser: {e}", flush=True)

    # Remove lock files so new instance doesn't attach to old session
    for lock_file in ['SingletonLock', 'SingletonSocket', 'SingletonCookie']:
        lock_path = os.path.join(profile_dir, lock_file)
        if os.path.exists(lock_path):
            try:
                os.remove(lock_path)
            except Exception:
                pass



def purge_gpu_caches(session_folder, label=""):
    """Delete GPU/shader caches from a Chrome profile after golden restore.

    The golden was created on a machine with a real GPU. The VPS runs Xvfb
    (software renderer). Chrome caches compiled shaders keyed to the GPU
    device/driver. When those caches are restored on a different GPU environment
    they are invalid — Chrome's GPU process crashes on the first real render.

    Deleting them forces Chrome to rebuild from scratch for Xvfb.
    Login cookies and session state are NOT affected.
    """
    prefix = f"[{label}] " if label else ""
    cache_dirs = [
        os.path.join(session_folder, "Default", "GPUCache"),
        os.path.join(session_folder, "GrShaderCache"),
        os.path.join(session_folder, "ShaderCache"),
    ]
    for d in cache_dirs:
        if os.path.exists(d):
            try:
                shutil.rmtree(d)
                print(f"{prefix}✓ Purged GPU cache: {os.path.basename(d)}", flush=True)
            except Exception as e:
                print(f"{prefix}⚠ Could not purge {os.path.basename(d)}: {e}", flush=True)

def restore_from_golden(session_folder, account_label="", restore_session=True,
                        # Legacy params kept for call-site compat — ignored in v126+
                        download_folder=None, restore_download=False):
    """Restore submit session profile from the golden (clean-login) snapshot.

    In v126+ the download browser is a tab in the same Chrome as the submit browser.
    Only the session profile needs to be restored — download_folder is no longer used.

    Returns True if restore succeeded, False otherwise.
    """
    golden_folder = get_golden_folder(session_folder)
    prefix = f"[{account_label}] " if account_label else ""

    if not os.path.exists(golden_folder):
        print(f"{prefix}⚠ Golden profile not found at {golden_folder} — cannot restore.", flush=True)
        print(f"{prefix}  Re-run setup_worker.py to create a fresh golden profile.", flush=True)
        return False

    if not restore_session or not session_folder:
        return True

    print(f"{prefix}🔄 GOLDEN RESTORE: Restoring session profile from {golden_folder}", flush=True)

    # v701g — Windows file-handle release loop. After taskkill on a Chrome
    # PID, the OS may hold memory-mapped file handles open for several
    # seconds. shutil.copytree then fails with WinError 1224 ("file with
    # a user-mapped section open") on cookie/cache databases. Old code
    # gave up immediately and shipped a partially-restored profile —
    # session has stale fragments mixed with golden state, reCAPTCHA
    # flags as suspicious, login drifts.
    #
    # Retry with backoff: 0.5s, 2s, 5s. After each failed attempt, force
    # one more pass at SingletonLock cleanup + small sleep so any
    # lingering chrome subprocess gets to release handles.
    last_err = None
    for _attempt in range(3):
        try:
            if os.path.exists(session_folder):
                shutil.rmtree(session_folder, ignore_errors=True)
            # Use dirs_exist_ok=True so if rmtree left locked files behind,
            # copytree still overwrites everything from golden rather than
            # failing with FileExistsError — session is always a clean copy
            # of golden.
            shutil.copytree(
                golden_folder, session_folder,
                dirs_exist_ok=True,
                ignore_dangling_symlinks=True,
                ignore=shutil.ignore_patterns(
                    'SingletonLock', 'SingletonSocket', 'SingletonCookie',
                ),
            )
            print(f"{prefix}  ✓ Session profile restored → {session_folder}", flush=True)
            last_err = None
            break
        except Exception as e:
            last_err = e
            err_str = str(e)
            # WinError 1224 = file mapped by another process. WinError 32 =
            # file in use. Both indicate "wait for handle release".
            if '1224' in err_str or 'WinError 32' in err_str or 'in use' in err_str.lower():
                _wait = (0.5, 2.0, 5.0)[_attempt] if _attempt < 3 else 5.0
                print(
                    f"{prefix}  ⚠ Restore attempt {_attempt+1}/3 hit Windows file-lock; "
                    f"waiting {_wait:.1f}s for handles to release",
                    flush=True,
                )
                # Aggressive cleanup between retries: also try to remove the
                # locked Singleton* files from session_folder if they exist.
                for _lock in ('SingletonLock', 'SingletonSocket', 'SingletonCookie'):
                    _lp = os.path.join(session_folder, _lock)
                    if os.path.exists(_lp):
                        try:
                            os.remove(_lp)
                        except Exception:
                            pass
                time.sleep(_wait)
                continue
            # Non-lock error — don't waste time retrying.
            break
    if last_err is not None:
        print(f"{prefix}  ⚠ Failed to restore session profile after retries: {last_err}", flush=True)
        return False

    # Purge GPU/shader caches — identical to what startup does after golden copy.
    # Golden was built on a potentially different GPU environment.
    purge_gpu_caches(session_folder, label=account_label or "RESTORE")

    print(f"{prefix}✅ Golden restore complete.", flush=True)
    return True


